func:
if (msg.payload.status === "online") {
    msg.payload = "🟢 ONLINE";
} else {
    msg.payload = "🔴 OFFLINE";
}

return msg;

msg.monitor = {
    topic: msg.topic,
    timestamp: new Date().toLocaleString(),
    payload: msg.payload
};

return msg;

let payloadValue = msg.payload;

if (typeof payloadValue === "string") {
    try {
        payloadValue = JSON.parse(payloadValue);
    } catch (e) {
        // keep plain string if it is not JSON
    }
}

msg.payload = {
    topic: msg.topic || "Unknown topic",
    timestamp: new Date().toLocaleString(),
    data: payloadValue
};

return msg;

// Parse MQTT payload if it is a JSON string.
let payload = msg.payload;

if (typeof payload === "string") {
    try {
        payload = JSON.parse(payload);
    } catch (error) {
        node.error("Invalid weather JSON", msg);
        return null;
    }
}

if (!payload || typeof payload !== "object") {
    node.warn("Invalid weather payload");
    return null;
}

// Extract the nested weather object.
const weather = payload.weather || payload;

// Normalize the backend fields to match the dashboard.
msg.section = "weather";

msg.payload = {
    temperature: weather.temperature ?? null,

    // The current backend supplies a Boolean rain_expected,
    // not a numeric rain probability.
    rain_probability:
        typeof weather.rain_expected === "boolean"
            ? (weather.rain_expected ? "Expected" : "Not expected")
            : null,

    condition:
        weather.description ??
        weather.condition ??
        "Unavailable",

    forecast:
        weather.watering_hint ??
        weather.forecast ??
        "No watering guidance available"
};

return msg;

// Parse MQTT payload if it is a JSON string.
let payload = msg.payload;

if (typeof payload === "string") {
    try {
        payload = JSON.parse(payload);
    } catch (error) {
        node.error("Invalid notifications JSON", msg);
        return null;
    }
}

if (!payload || typeof payload !== "object") {
    node.warn("Invalid notifications payload");
    return null;
}

const delivery = payload.email_delivery || {};

const emails = Array.isArray(payload.recent_care_emails)
    ? payload.recent_care_emails
    : [];

// Build a summary from the actual backend fields.
const emailStatus = delivery.status || "unknown";

let deliverySummary;

if (delivery.sent === true) {
    deliverySummary = "Care summary email sent successfully.";
} else if (emailStatus === "skipped_duplicate") {
    deliverySummary =
        "Email not sent because the care notification was a duplicate.";
} else if (emailStatus === "unknown") {
    deliverySummary = "Email delivery status is unavailable.";
} else {
    deliverySummary = `Email delivery status: ${emailStatus}.`;
}

const fetchStatus = payload.email_fetch_status || "unknown";

const fetchSummary =
    fetchStatus === "success"
        ? `${emails.length} recent care email(s) retrieved.`
        : `Care email retrieval status: ${fetchStatus}.`;

// Route and normalize for the existing dashboard.
msg.section = "notifications";

msg.payload = {
    count: emails.length,

    summary: `${deliverySummary} ${fetchSummary}`,

    email_delivery_status: emailStatus,
    email_sent: delivery.sent === true,
    urgency: payload.urgency || "UNKNOWN",
    recommendation: payload.recommendation || "",
    recent_care_emails: emails,
    email_fetch_status: fetchStatus
};

return msg;
